Given a word pattern and a string text consisting of lowercase characters, find the count of substrings in text which are anagrams of the pattern.Examples: Input : text = "forxxorfxdofr", pattern = "for"Output : 3Explanation : Anagrams present are for, orf and ofr. Each appears in the text once and hence the count is 3.Input : text = "aabaabaa", pattern = "aaba"Output : 4Explanation : Anagrams present are aaba and abaa. Each appears twice in the text and hence the count is 4.Try It YourselfTable of Content [Naive] Substring Checking - O(n * m) time and O(1) space[Optimal] Sliding Window - O(n + m) time and O(1) space [Naive] Substring Checking - O(n * m) time and O(1) spaceTraverse the string and check every substring whose length equals the pattern. For each substring, verify whether it contains all the characters of the word.
            C++

    #include <iostream>
#include <vector>
#include <string>

using namespace std;

// Function to check if two strings are anagrams
bool areAnagram(string s1, string s2) {
    vector<int> cnt(26, 0);

    int n1 = s1.length();
    int n2 = s2.length();

    for (int i = 0; i < n1; i++)
        cnt[s1[i] - 'a']++;

    for (int i = 0; i < n2; i++)
        cnt[s2[i] - 'a']--;

    for (int i = 0; i < 26; i++) {
        if (cnt[i] != 0)
            return false;
    }

    return true;
}

int search(string &pattern, string &text) {

    // Initialize result
    int res = 0;

    int n = text.length();
    int m = pattern.length();

    for (int i = 0; i <= n - m; i++) {

        // Check if substring and pattern are anagrams
        if (areAnagram(text.substr(i, m), pattern))
            res++;
    }

    return res;
}

int main() {

    string text = "forxxorfxdofr";
    string pattern = "for";

    cout << search(pattern, text);

    return 0;
}


