    #include <iostream>
#include <vector>
#include <string>

using namespace std;

// Two strings are anagram if the count
// of characters of each string cancel
// each other out.
bool isAnagram(vector<int> &cnt) {
    for (int i = 0; i < 26; i++) {
        if (cnt[i] != 0) return false;
    }
    return true;
}

int search(string &pattern, string &text) {

    int m = pattern.length();
    int n = text.length();

    // If pattern length is greater than text length
    if (m > n) return 0;

    vector<int> cnt(26, 0);

    // Count characters of pattern
    for (char ch : pattern) {
        cnt[ch - 'a']++;
    }

    // Process first window (size m-1)
    for (int i = 0; i < m - 1; i++) {
        cnt[text[i] - 'a']--;
    }

    int ans = 0;

    // Sliding window
    for (int i = m - 1; i < n; i++) {

        // Add new character
        cnt[text[i] - 'a']--;

        // Check anagram
        if (isAnagram(cnt)) ans++;

        // Remove first character of window
        cnt[text[i - m + 1] - 'a']++;
    }

    return ans;
}

int main() {
    string text = "forxxorfxdofr";
    string pattern = "for";

    cout << search(pattern, text);

    return 0;
}


